"""
Successor function for the Satellite domain.

States are lists of {"predicate": str, "args": [str, ...]} dictionaries.
The function returns lists in the same format representing all states
reachable through a single grounded action.
"""
from __future__ import annotations

from typing import Dict, Iterable, List, Sequence, Set, Tuple

Fact = Tuple[str, Tuple[str, ...]]
State = List[Dict[str, Sequence[str]]]


def _state_signature(state: State) -> Tuple[Fact, ...]:
    """Create a canonical signature for matching states across files."""
    return tuple(sorted((fact["predicate"], tuple(fact.get("args", ())))
                        for fact in state))

