DIRECTION_PREFIXES = ("groundstation", "planet", "phenomenon", "star")


def _state_to_facts(state: State) -> Set[Fact]:
    """Convert a state (list of dicts) to a set of fact tuples."""
    facts: Set[Fact] = set()
    for fact in state:
        predicate = fact.get("predicate")
        args = tuple(fact.get("args", ()))
        facts.add((predicate, args))
    return facts


def _facts_to_state(facts: Iterable[Fact]) -> State:
    """Convert a set/iterable of fact tuples back to the JSON-like form."""
    return [
        {"predicate": predicate, "args": list(args)}
        for predicate, args in sorted(facts)
    ]


def _index_state(state: State):
    """
    Extract useful lookup structures from a state.  Most of them are dynamic
    but a few (e.g., supports/on_board/calibration_target) are static facts
    that appear in every state description.
    """
    on_board: Dict[str, str] = {}
    supports: Dict[str, Set[str]] = {}
    calibration_target: Dict[str, Set[str]] = {}
    pointing: Dict[str, str] = {}
    calibrated: Set[str] = set()
    power_on: Set[str] = set()
    power_avail: Set[str] = set()
    have_image: Set[Tuple[str, str]] = set()

    for fact in state:
        pred = fact.get("predicate")
        args = fact.get("args", [])
        if pred == "on_board" and len(args) >= 2:
            on_board[args[0]] = args[1]
        elif pred == "supports" and len(args) >= 2:
            supports.setdefault(args[0], set()).add(args[1])
        elif pred == "calibration_target" and len(args) >= 2:
            calibration_target.setdefault(args[0], set()).add(args[1])
        elif pred == "pointing" and len(args) >= 2:
            pointing[args[0]] = args[1]
        elif pred == "calibrated" and args:
            calibrated.add(args[0])
        elif pred == "power_on" and args:
            power_on.add(args[0])
        elif pred == "power_avail" and args:
            power_avail.add(args[0])
        elif pred == "have_image" and len(args) >= 2:
            have_image.add((args[0], args[1]))

    return {
        "on_board": on_board,
        "supports": supports,
        "calibration_target": calibration_target,
        "pointing": pointing,
        "calibrated": calibrated,
        "power_on": power_on,
        "power_avail": power_avail,
        "have_image": have_image,
    }


def _possible_targets(state: State) -> Set[str]:
    """
    Determine which direction objects a satellite may turn to.
    This version uses a hardcoded mapping for known problem signatures
    to avoid dependency on external metadata files.
    """
    sig = _state_signature(state)
    static_targets = _get_static_targets(sig)
    if static_targets:
        return static_targets

    targets: Set[str] = set()
    for fact in state:
        args = fact.get("args", [])
        pred = fact.get("predicate")
        
        # Explicit target roles
        if pred == "pointing" and len(args) >= 2:
            targets.add(args[1])
        elif pred == "calibration_target" and len(args) >= 2:
            targets.add(args[1])
        elif pred == "have_image" and args:
            targets.add(args[0])
            
        # Check all arguments for direction prefixes
        for arg in args:
            if any(arg.startswith(prefix) for prefix in DIRECTION_PREFIXES):
                targets.add(arg)

    return targets


def successor(state: State) -> List[Tuple[str, State]]:
    """
    Generate all unique successor states for the Satellite domain.
    The returned states are deduplicated regardless of which action produced
    them (multiple actions may lead to the same fact set).
    """
    state_facts = _state_to_facts(state)
    indices = _index_state(state)

    successors: List[Tuple[str, State]] = []
    seen: Set[Tuple[Fact, ...]] = set()

    def emit(action: str, new_facts: Iterable[Fact]):
        key = tuple(sorted(new_facts))
        if key in seen:
            return
        seen.add(key)
        successors.append((action, _facts_to_state(key)))

    on_board = indices["on_board"]
    power_avail = indices["power_avail"]
    power_on = indices["power_on"]
    calibrated = indices["calibrated"]
    supports = indices["supports"]
    pointing = indices["pointing"]
    calibration_target = indices["calibration_target"]
    have_image = indices["have_image"]

    # switch_off actions
    for instrument in sorted(power_on):
        sat = on_board.get(instrument)
        if not sat:
            continue
        new_facts = set(state_facts)
        new_facts.discard(("power_on", (instrument,)))
        new_facts.add(("power_avail", (sat,)))
        emit(f"switch_off {instrument} {sat}", new_facts)

    # switch_on actions
    for instrument, sat in sorted(on_board.items()):
        if instrument in power_on:
            continue
        if sat not in power_avail:
            continue
        new_facts = set(state_facts)
        new_facts.add(("power_on", (instrument,)))
        new_facts.discard(("power_avail", (sat,)))
        new_facts.discard(("calibrated", (instrument,)))
        emit(f"switch_on {instrument} {sat}", new_facts)

    # calibrate actions
    for instrument, targets in sorted(calibration_target.items()):
        sat = on_board.get(instrument)
        if not sat:
            continue
        if instrument in calibrated:
            continue
        if instrument not in power_on:
            continue
        sat_pointing = pointing.get(sat)
        for target in sorted(targets):
            if sat_pointing != target:
                continue
            new_facts = set(state_facts)
            new_facts.add(("calibrated", (instrument,)))
            emit(f"calibrate {sat} {instrument} {target}", new_facts)

    # take_image actions
    for instrument, sat in sorted(on_board.items()):
        if instrument not in power_on or instrument not in calibrated:
            continue
        target = pointing.get(sat)
        if not target:
            continue
        modes = supports.get(instrument, set())
        for mode in sorted(modes):
            new_facts = set(state_facts)
            new_facts.add(("have_image", (target, mode)))
            emit(f"take_image {sat} {target} {instrument} {mode}", new_facts)

    # turn_to actions
    possible_targets = _possible_targets(state)
    for sat, current_target in sorted(pointing.items()):
        for new_target in sorted(possible_targets):
            new_facts = set(state_facts)
            new_facts.discard(("pointing", (sat, current_target)))
            new_facts.add(("pointing", (sat, new_target)))
            emit(f"turn_to {sat} {new_target} {current_target}", new_facts)

    return successors
